script:
const id=api.sceneName;
const hero=api.getByTag('heroi');
const gate=api.get('Portal de saída');
const counter=api.get('Contador');
scene.__nr=scene.__nr||{};
const s=scene.__nr;
if(s.stage!==id){
 s.stage=id;s.open=false;s.finished=false;s.cooldown=0;s.boost=0;s.shield=0;s.shieldCd=0;s.prevA=false;s.prevB=false;
 api.message('FASE 1/3 · Colete 5 fragmentos e encontre o portal!',4);
}
s.cooldown=Math.max(0,s.cooldown-dt);
s.shieldCd=Math.max(0,s.shieldCd-dt);
s.boost=Math.max(0,s.boost-dt);
s.shield=Math.max(0,s.shield-dt);
if(hero){
 const B=!!api.input.action,A=!!api.input.jump;
 if(B&&!s.prevB&&s.cooldown<=0){s.cooldown=6;s.boost=1.35;api.sound(660,.13);api.emitParticles(hero.x,hero.y,12,'#51ffef');api.message('⚡ TURBO ativado!',1.5);}
 if(A&&!s.prevA&&s.shieldCd<=0){s.shieldCd=10;s.shield=1.6;api.sound(880,.13);api.emitParticles(hero.x,hero.y,20,'#8eaeff');api.message('🛡 ESCUDO por 1,6 s!',1.5);}
 s.prevA=A;s.prevB=B;
 hero.speed=s.boost>0?420:235;
 hero.color=s.shield>0?'#a5baff':(s.boost>0?'#fff4a0':'#5cfbe1');
 for(const enemy of api.getAll('perigo')){
  for(const component of enemy.components||[])if(component.type==='hazard')component.enabled=s.shield<=0;
 }
}
if(counter)counter.text='FRAGMENTOS: '+Math.min(5,Math.max(0,api.score()-0))+' / 5     A = ESCUDO   B = TURBO';
if(gate){
 const unlocked=api.score()>=5;
 gate.visible=unlocked;
 if(unlocked&&!s.open){s.open=true;api.message('PORTAL LIBERADO! Vá para a saída à direita →',4);api.sound(1047,.15);api.cameraShake(3);}
 if(unlocked&&hero&&api.overlap(hero,gate)&&!s.finished){s.finished=true;api.sound(1320,.2);api.emitParticles(gate.x,gate.y,32,'#b7fff2');api.nextScene();}
}

